const item = $input.first().json;
const missing = [];
if (!item.clientName || item.clientName.trim().length < 2) missing.push('Client Name');
if (!item.projectDescription || item.projectDescription.trim().length < 10) missing.push('Project Description (needs more detail)');
if (!item.deliverables || item.deliverables.trim().length < 5) missing.push('Deliverables');

return [{ json: { ...item, inputValid: missing.length === 0, missingFields: missing.join(', ') } }];

const item = $input.first().json;

const systemPrompt = `You are a senior proposal writer for a freelance AI automation and full-stack development agency. You will be given client requirements and a rate card. Respond with ONLY a single valid JSON object, no markdown fences, no preamble, matching exactly this shape: {"proposal": {"title": string, "summary": string, "approach": string}, "timeline": [{"phase": string, "description": string, "duration": string}], "costEstimate": {"lineItems": [{"item": string, "detail": string, "amount": string}], "total": string, "paymentTerms": string}, "scopeDocument": {"inScope": [string], "outOfScope": [string], "assumptions": [string]}}. Base all pricing strictly on the provided rate card ranges, never invent numbers outside it. Keep language concise, confident, and human -- never generic or templated-sounding.`;

const userContent = `Client: ${item.clientName}
Contact: ${item.contactPerson}
Industry: ${item.industry}
Project description: ${item.projectDescription}
Requested deliverables: ${item.deliverables}
Budget range given by client: ${item.budgetRange}
Deadline: ${item.deadline}

Rate card to base pricing on:
${item.rateCardText}

Generate the full proposal JSON now.`;

const requestBody = {
  model: "llama-3.3-70b-versatile",
  max_tokens: 3000,
  response_format: { type: "json_object" },
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: userContent }
  ]
};

return [{ json: { ...item, requestBody } }];

const raw = $input.first().json.choices[0].message.content;
let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```json\n?/, '').replace(/^```\n?/, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { valid: false, error: 'Failed to parse AI response as JSON', raw: cleaned } }];
}

const required = ['proposal', 'timeline', 'costEstimate', 'scopeDocument'];
const missing = required.filter(k => !(k in parsed));
if (missing.length) {
  return [{ json: { valid: false, error: `Missing fields: ${missing.join(', ')}`, raw: cleaned } }];
}

return [{ json: { valid: true, ...parsed } }];

const client = $('Normalize Input').first().json;
const business = $('Business & Rate Card (Edit Me)').first().json;
const data = $input.first().json;

const brand = business.brandColor || '#0f172a';

const timelineRows = data.timeline.map(t => `
  <tr>
    <td>${t.phase}</td>
    <td>${t.description}</td>
    <td>${t.duration}</td>
  </tr>`).join('');

const costRows = data.costEstimate.lineItems.map(i => `
  <tr>
    <td>${i.item}</td>
    <td>${i.detail}</td>
    <td class="amt">${i.amount}</td>
  </tr>`).join('');

const inScope = data.scopeDocument.inScope.map(s => `<li>${s}</li>`).join('');
const outScope = data.scopeDocument.outOfScope.map(s => `<li>${s}</li>`).join('');
const assumptions = data.scopeDocument.assumptions.map(s => `<li>${s}</li>`).join('');

const today = new Date();
const dateStr = today.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
const refCode = `${(client.clientName || 'CLT').replace(/[^A-Za-z]/g, '').slice(0, 3).toUpperCase()}-${today.getFullYear()}${String(today.getMonth() + 1).padStart(2, '0')}${String(today.getDate()).padStart(2, '0')}`;

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  * { box-sizing: border-box; }
  body { font-family: 'Helvetica Neue', Arial, sans-serif; color: #1f2937; margin: 0; padding: 50px 55px; font-size: 13px; line-height: 1.6; }
  .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid ${brand}; padding-bottom: 16px; margin-bottom: 26px; }
  .brand-name { font-size: 20px; font-weight: 700; color: ${brand}; margin: 0; }
  .brand-tagline { font-size: 11px; color: #6b7280; margin-top: 3px; }
  .doc-meta { text-align: right; font-size: 11px; color: #6b7280; line-height: 1.5; }
  .doc-meta .doc-type { font-size: 11px; font-weight: 700; letter-spacing: 0.08em; color: ${brand}; text-transform: uppercase; }
  .prepared-for { margin-bottom: 26px; }
  .prepared-for .label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: #9ca3af; }
  .prepared-for .name { font-size: 16px; font-weight: 600; color: #111827; margin-top: 2px; }
  h1.title { font-size: 21px; margin: 0 0 22px 0; color: #111827; }
  h2 { font-size: 12px; text-transform: uppercase; letter-spacing: 0.07em; color: ${brand}; margin-top: 28px; margin-bottom: 8px; padding-bottom: 6px; border-bottom: 1px solid #e5e7eb; }
  p { margin: 6px 0 0 0; }
  table { width: 100%; border-collapse: collapse; margin-top: 8px; }
  th, td { text-align: left; padding: 9px 10px; border-bottom: 1px solid #e5e7eb; vertical-align: top; }
  th { background: #f8fafc; font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; color: #6b7280; }
  .amt { text-align: right; white-space: nowrap; }
  .total-row td { font-weight: 700; border-top: 2px solid ${brand}; background: #f8fafc; }
  ul { margin: 6px 0; padding-left: 20px; }
  li { margin-bottom: 3px; }
  .signature-block { margin-top: 42px; display: flex; gap: 60px; }
  .sig-line { flex: 1; border-top: 1px solid #9ca3af; padding-top: 6px; font-size: 11px; color: #6b7280; }
  .footer { margin-top: 36px; padding-top: 14px; border-top: 1px solid #e5e7eb; font-size: 10px; color: #9ca3af; text-align: center; }
</style>
</head>
<body>
  <div class="header">
    <div>
      <p class="brand-name">${business.businessName || 'Your Business Name'}</p>
      <p class="brand-tagline">${business.tagline || ''}</p>
    </div>
    <div class="doc-meta">
      <div class="doc-type">Proposal</div>
      <div>Ref: ${refCode}</div>
      <div>${dateStr}</div>
    </div>
  </div>

  <div class="prepared-for">
    <div class="label">Prepared exclusively for</div>
    <div class="name">${client.contactPerson}${(client.clientName && client.clientName !== client.contactPerson) ? ' · ' + client.clientName : ''}</div>
  </div>

  <h1 class="title">${data.proposal.title}</h1>

  <h2>Summary</h2>
  <p>${data.proposal.summary}</p>

  <h2>Approach</h2>
  <p>${data.proposal.approach}</p>

  <h2>Timeline</h2>
  <table>
    <tr><th>Phase</th><th>Description</th><th>Duration</th></tr>
    ${timelineRows}
  </table>

  <h2>Investment</h2>
  <table>
    <tr><th>Item</th><th>Detail</th><th class="amt">Amount</th></tr>
    ${costRows}
    <tr class="total-row"><td colspan="2">Total</td><td class="amt">${data.costEstimate.total}</td></tr>
  </table>
  <p style="font-style: italic; color: #6b7280;">${data.costEstimate.paymentTerms}</p>

  <h2>Scope of Work</h2>
  <p><strong>Included:</strong></p><ul>${inScope}</ul>
  <p><strong>Not included:</strong></p><ul>${outScope}</ul>
  <p><strong>Assumptions:</strong></p><ul>${assumptions}</ul>

  <div class="signature-block">
    <div class="sig-line">Client Signature &nbsp;&nbsp;&nbsp;&nbsp; Date</div>
    <div class="sig-line">${business.businessName || 'Provider'} &nbsp;&nbsp;&nbsp;&nbsp; Date</div>
  </div>

  <div class="footer">${business.businessName || ''} &nbsp;·&nbsp; ${client.freelancerEmail} &nbsp;·&nbsp; This proposal is valid for 14 days from the date above.</div>
</body>
</html>`;

return [{ json: { html } }];

const client = $('Normalize Input').first().json;
const date = new Date().toISOString().split('T')[0];
const safeName = (client.clientName || 'Client').replace(/[^a-z0-9]/gi, '_');
const filename = `${safeName}_Proposal_${date}.pdf`;

return $input.all().map(item => ({
  json: { ...item.json, filename, clientName: client.clientName, clientEmail: client.clientEmail, freelancerEmail: client.freelancerEmail },
  binary: {
    data: {
      ...item.binary.data,
      fileName: filename,
      mimeType: 'application/pdf'
    }
  }
}));

const originalPdfItem = $('Set PDF Filename').first();
const loggedData = $input.first().json;

let driveLink = '';
try {
  const driveItem = $('Upload to Drive').first();
  if (driveItem && driveItem.json && driveItem.json.webViewLink) {
    driveLink = driveItem.json.webViewLink;
  }
} catch (e) {
  driveLink = '';
}

return [{
  json: { ...originalPdfItem.json, ...loggedData, webViewLink: driveLink },
  binary: originalPdfItem.binary
}];

const inputItem = $input.first();
const item = inputItem.json;
const business = $('Business & Rate Card (Edit Me)').first().json;

const driveLine = item.webViewLink
  ? `Your AI-generated proposal for <strong>${item.clientName}</strong> is attached and saved to Drive: <a href="${item.webViewLink}">${item.webViewLink}</a>`
  : `Your AI-generated proposal for <strong>${item.clientName}</strong> is attached. (Drive save didn't complete this time, but the PDF is right here.)`;

const emailSubject = `Proposal ready for ${item.clientName} — review before sending`;
const emailBody = `${driveLine}<br><br>Give it a quick read, then forward it to ${item.clientEmail} once you're happy with it.`;

return [{
  json: { ...item, emailSubject, emailBody },
  binary: inputItem.binary
}];
